// Writes docs/CONTENT-REVIEW.md: the full script with every number, for review
// by a developmental-coaching expert. Generated from src/content/maya.js,
// src/engine.js (RULES) and tests/calibrate.mjs. Run from turn-the-page/:
//   node tests/export-review.mjs
// Do not edit CONTENT-REVIEW.md by hand; change the sources and re-run.
import { writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { RULES, computeDeltas, routeFor } from '../src/engine.js';
import { MAYA } from '../src/content/maya.js';
import { calibrate } from './calibrate.mjs';
import { wordingTells } from './wording-tells.mjs';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const C = MAYA;
const out = [];
const w = (s) => out.push(s === undefined ? '' : s);
const LEVER_NAME = { question: 'Question', support: 'Support', observe: 'Observe', challenge: 'Challenge' };
const signed = (n) => (n > 0 ? '+' : n < 0 ? '−' : '±') + Math.abs(n);
const row = (d) => RULES.meters.map((m) => m[0].toUpperCase() + ' ' + signed(d[m] || 0)).join(', ');
const esc = (s) => String(s).replace(/\|/g, '\\|');

// Reference states for the "deltas" columns. Deltas depend on the meters,
// the traits, the act and recent history, so two fixed states are shown,
// each with no history: the round's starting meters, and the same with Trust 55.
const R2_REF = { meters: { trust: RULES.carry.polite.trust, confidence: C.profile.start.confidence, ownership: C.profile.start.ownership }, traits: C.profile.traits };
function refStates(rid) {
  const base = rid === 'r1' ? { meters: C.profile.start, traits: C.profile.traits } : R2_REF;
  return [
    { label: 'at start (T ' + base.meters.trust + ')', meters: base.meters, traits: base.traits },
    { label: 'at T 55', meters: Object.assign({}, base.meters, { trust: 55 }), traits: base.traits }
  ];
}
function deltas(option, node, ref) {
  return computeDeltas({ lever: option.lever, quality: option.quality || 'skilful', meters: ref.meters, traits: ref.traits, act: node.act, history: [], override: option.override }).delta;
}

function describeRoute(r) {
  if (r === null) return 'end of round';
  if (typeof r === 'string') return r;
  if (Array.isArray(r)) return r.map((x) => x.to + (x.if ? ' if ' + Object.entries(x.if).map(([m, c]) => m + (c.min !== undefined ? ' ≥ ' + c.min : '') + (c.max !== undefined ? ' ≤ ' + c.max : '')).join(' and ') : ' otherwise')).join('; ');
  return Object.entries(r).map(([k, v]) => k + ' → ' + describeRoute(v)).join('; ');
}

// Bridged texts (SPEC.md 9.5): a string, or { default, from }.
const plain = (x) => (x && typeof x === 'object' ? x.default : x) || '';
const bridges = []; // { round, dest, field, key, text }
function collect(rid, dest, field, x) {
  if (x && typeof x === 'object') for (const [key, text] of Object.entries(x.from)) bridges.push({ rid, dest, field, key, text });
}
function fromLabel(rid, key) {
  const [nid, oid] = key.split(':');
  const n = C.rounds[rid].nodes[nid];
  const o = n.options.find((x) => x.id === oid);
  return 'p. ' + n.page + ' `' + key + '` ' + LEVER_NAME[o.lever] + (o.quality ? ' (' + o.quality + ')' : '');
}

function strings(x, acc) {
  if (typeof x === 'string') acc.push(x);
  else if (x && typeof x === 'object') for (const v of Object.values(x)) strings(v, acc);
  return acc;
}

// --- Header -----------------------------------------------------------------
w('# Turn the Page — content review');
w();
w('*Generated by `tests/export-review.mjs` from `src/content/maya.js`, `src/engine.js` and `tests/calibrate.mjs`. Do not edit by hand.*');
w();
w('This document is for review by a developmental-coaching expert. It contains the whole script for both rounds, every number the engine uses, every hand-tuned override and the calibration report. Every scoring value is an initial value and every trait mapping is a design hypothesis (SPEC.md 1, 7); none is an empirical finding.');
w();
w('How to read the scripts: each page shows what Maya says, what the counsellor can see, and the options. For each option: the lever, the wording quality (Round 1 only), Maya\'s reaction, any override, the meter change it causes in two reference states, and the debrief note. The reference states have no previous choices; in play, repetition and the meters at that moment change the numbers. **Round 1 reference:** Maya\'s starting meters (Trust ' + C.profile.start.trust + ', Confidence ' + C.profile.start.confidence + ', Ownership ' + C.profile.start.ownership + '), and the same with Trust 55. **Round 2 reference:** the "after Polite exit" start (Trust ' + R2_REF.meters.trust + ', Confidence ' + R2_REF.meters.confidence + ', Ownership ' + R2_REF.meters.ownership + ', readiness low), and the same with Trust 55. T = Trust, C = Confidence, O = Ownership.');
w();
w('Contents: [Maya](#maya) · [Round 1](#round-1-just-lazy) · [Round 2](#round-2-two-weeks-later) · [Bridges](#bridging-lines-and-branch-pages) · [Turning points](#turning-points-and-road-not-taken) · [Overrides](#every-override) · [Rules](#rules-table) · [Calibration](#calibration-report) · [Placeholders](#placeholder-strings)');
w();

// --- Maya ------------------------------------------------------------------
const P = C.profile;
w('## Maya');
w();
w('- **Name and age:** ' + P.name + ', ' + P.age);
w('- **Stage:** ' + P.stage);
for (const c of P.context) w('- ' + c);
w('- **Traits (hidden in play):** ' + Object.entries(P.traits).map(([k, v]) => k + ' `' + v + '`').join(', ') + '. Readiness rises one band in Round 2 after a Breakthrough or Partial ending.');
w('- **Starting meters:** ' + RULES.meters.map((m) => m + ' ' + P.start[m]).join(', '));
w();
w('**' + C.referral.title + '** — Student: ' + C.referral.student + ' · Referred by: ' + C.referral.from);
w();
w('> ' + C.referral.text);
w();
w('| Hint in the note | Trait | Debrief note |');
w('|---|---|---|');
for (const h of C.referral.hints) w('| ' + esc(h.text) + ' | ' + h.trait + ' | ' + esc(h.note) + ' |');
w();

// --- Rounds ----------------------------------------------------------------
const overrides = [];
const ROUND_TITLES = { r1: 'Round 1: Just lazy', r2: 'Round 2: Two weeks later' };
for (const [rid, round] of Object.entries(C.rounds)) {
  const nodes = round.nodes;
  w('## ' + ROUND_TITLES[rid]);
  w();
  w('Format ' + round.format + (round.format === 'B' ? ': the counsellor picks a lever, then one of three wordings (skilful, plausible or clumsy, unlabelled, shuffled).' : ': four unlabelled, shuffled lines, one per lever, all competent; then the counsellor names the lever.') + ' ' + Object.keys(nodes).length + ' pages.');
  w();
  if (round.starts) {
    w('Opening page by Round 1 ending: ' + Object.entries(round.starts).map(([e, n]) => e + ' → ' + n).join(', ') + '.');
    w();
    if (round.interlude) {
      w('Interlude ("Two weeks later"), shown before the opening page:');
      w();
      w('| Round 1 ending | Interlude text |');
      w('|---|---|');
      for (const [e, t] of Object.entries(round.interlude)) w('| ' + e + ' | ' + esc(t) + ' |');
      w();
    }
    if (round.carryNote) {
      w('How the Round 1 ending shaped this opening (Debrief 2, "Two sessions side by side"):');
      w();
      w('| Round 1 ending | Note |');
      w('|---|---|');
      for (const [e, t] of Object.entries(round.carryNote)) w('| ' + e + ' | ' + esc(t) + ' |');
      w();
    }
  }
  w('| Act | Title | Cliffhanger (act banner) |');
  w('|---|---|---|');
  for (const [a, x] of Object.entries(round.acts)) w('| ' + a + ' | ' + x.title + ' | ' + esc(x.cliffhanger) + ' |');
  w();

  // Node map.
  w('### Node map');
  w();
  w('```mermaid');
  w('flowchart TD');
  const id = (n) => n.replace(/-/g, '_');
  const acts = {};
  for (const [nid, n] of Object.entries(nodes)) (acts[n.act] = acts[n.act] || []).push(nid);
  if (round.starts) {
    for (const [e, n] of Object.entries(round.starts)) w('  start_' + e + '([R1 ' + e + ']) --> ' + id(n));
  } else {
    w('  start([Start]) --> ' + id(round.start));
  }
  for (const [a, ids] of Object.entries(acts)) {
    w('  subgraph act' + a + '_' + rid + ' [Act ' + a + ': ' + round.acts[a].title + ']');
    for (const nid of ids) w('    ' + id(nid) + '["' + nid + ' · p. ' + nodes[nid].page + '"]');
    w('  end');
  }
  w('  finish([Ending])');
  for (const [nid, n] of Object.entries(nodes)) {
    const edges = new Map();
    for (const o of n.options) {
      const r = routeFor(n, o);
      const targets = Array.isArray(r) ? r.map((x) => [x.to, x.if ? 'T ≥ ' + x.if.trust.min : 'else']) : [[r, '']];
      for (const [t, cond] of targets) {
        const key = (t === null ? 'finish' : id(t));
        const label = LEVER_NAME[o.lever] + (cond ? ', ' + cond : '');
        if (!edges.has(key)) edges.set(key, new Set());
        edges.get(key).add(label);
      }
    }
    for (const [t, labels] of edges) {
      // Drop the lever names when all four levers share the edge.
      const all = [...labels];
      const byCond = {};
      for (const l of all) { const [lv, cond] = l.split(', '); (byCond[cond || ''] = byCond[cond || ''] || []).push(lv); }
      const text = Object.entries(byCond).map(([cond, lvs]) => (lvs.length === 4 ? '' : lvs.join(' / ')) + (cond ? (lvs.length === 4 ? '' : ', ') + cond : '')).filter(Boolean).join(' / ');
      w('  ' + id(nid) + (text ? ' -->|' + text + '| ' : ' --> ') + t);
    }
  }
  w('```');
  w();

  // Script.
  w('### Script');
  w();
  const refs = refStates(rid);
  for (const [nid, n] of Object.entries(nodes)) {
    w('#### ' + nid + ' · p. ' + n.page + ' · Act ' + n.act);
    w();
    collect(rid, nid, 'line', n.line);
    collect(rid, nid, 'cue', n.cue);
    w('**Maya:** "' + plain(n.line) + '"' + (typeof n.line === 'object' ? ' *(+ ' + Object.keys(n.line.from).length + ' bridging line(s); see [Bridges](#bridging-lines-and-branch-pages))*' : ''));
    w();
    w('**Cue:** ' + plain(n.cue) + (typeof n.cue === 'object' ? ' *(+ ' + Object.keys(n.cue.from).length + ' bridging cue(s))*' : '') + (n.scene && n.scene.pose ? ' *(pose: ' + Object.entries(n.scene.pose).map(([k, v]) => k + ' ' + (Array.isArray(v) ? v.join('+') : v)).join(', ') + ')*' : ''));
    w();
    w('**Next:** ' + describeRoute(n.next));
    w();
    w('| Lever | Counsellor says | Maya\'s reaction | Override | Δ ' + refs[0].label + ' | Δ ' + refs[1].label + ' | Debrief note |');
    w('|---|---|---|---|---|---|---|');
    for (const o of n.options) {
      const lever = LEVER_NAME[o.lever] + (o.quality ? ' (' + o.quality + ')' : '');
      const r = typeof o.reaction === 'string' ? { default: o.reaction } : o.reaction;
      const pose = o.pose ? '<br>*(pose: ' + Object.entries(o.pose).map(([k, v]) => k + ' ' + (Array.isArray(v) ? (v.length ? v.join(', ') : 'none') : v)).join(', ') + ')*' : '';
      const reaction = Object.entries(r).map(([k, v]) => (k === 'default' ? '' : '*[' + k + ']* ') + v).join('<br>') + pose;
      const ov = o.override ? Object.entries(o.override).map(([m, v]) => m[0].toUpperCase() + ' ' + signed(v)).join(', ') : '—';
      if (o.override) overrides.push({ where: rid + ' / ' + nid + ' / ' + o.id, lever, text: o.text, ov });
      const own = Object.prototype.hasOwnProperty.call(o, 'next') ? ' → ' + describeRoute(o.next) : '';
      w('| ' + lever + own + ' | ' + esc(o.text) + ' | ' + esc(reaction) + ' | ' + ov + ' | ' + row(deltas(o, n, refs[0])) + ' | ' + row(deltas(o, n, refs[1])) + ' | ' + esc(o.debrief) + ' |');
    }
    w();
  }
  w('### Endings');
  w();
  w('| Ending | Title | Text | Debrief summary |');
  w('|---|---|---|---|');
  for (const [e, x] of Object.entries(round.endings)) collect(rid, 'end:' + e, 'text', x.text);
  for (const [e, x] of Object.entries(round.endings)) w('| ' + e + ' | ' + x.title + ' | ' + esc(plain(x.text)) + (typeof x.text === 'object' ? ' *(+ ' + Object.keys(x.text.from).length + ' bridging text(s))*' : '') + ' | ' + esc(x.summary) + (x.ownershipNote ? ' *If ownership ended high:* ' + esc(x.ownershipNote) : '') + ' |');
  w();
}

// --- Bridges -------------------------------------------------------------------
w('## Bridging lines and branch pages');
w();
w('Session 7 (SPEC.md 9.5). A bridging line replaces a page\'s opening line or cue, or an ending\'s text, when the page is reached straight from the page and option named; every other way in, and the page after a reload, shows the default. Presentation only: scores and routes do not change. Each bridge answers a pair rated "bridge" in `docs/FLOW-AUDIT.md`, which gives the reason. **Branch pages:** none; the audit found no jump that a bridge could not fix.');
w();
for (const rid of Object.keys(C.rounds)) {
  const list = bridges.filter((b) => b.rid === rid);
  w('### ' + (rid === 'r1' ? 'Round 1' : 'Round 2') + ' (' + list.length + ' bridging texts)');
  w();
  w('| Into | Replaces | After | Default | Bridging text |');
  w('|---|---|---|---|---|');
  for (const b of list) {
    const round = C.rounds[rid];
    const into = b.dest.startsWith('end:') ? 'Ending: ' + round.endings[b.dest.slice(4)].title : 'p. ' + round.nodes[b.dest].page + ' `' + b.dest + '`';
    const def = b.dest.startsWith('end:') ? plain(round.endings[b.dest.slice(4)].text) : plain(round.nodes[b.dest][b.field]);
    w('| ' + into + ' | ' + b.field + ' | ' + fromLabel(rid, b.key) + ' | ' + esc(def) + ' | ' + esc(b.text) + ' |');
  }
  w();
}

// --- Turning points ----------------------------------------------------------
w('## Turning points and road not taken');
w();
w('Highlighted in the debrief. The debrief shows the road-not-taken lines for the levers the counsellor did not choose there.');
w();
for (const [rid, ids] of Object.entries(C.turningPoints)) {
  for (const nid of ids) {
    w('**' + rid + ' / ' + nid + '** — "' + plain(C.rounds[rid].nodes[nid].line) + '"');
    w();
    for (const [l, t] of Object.entries(C.roadNotTaken[nid] || {})) w('- ' + LEVER_NAME[l] + ': ' + t);
    w();
  }
}

// --- Reflection prompts ------------------------------------------------------
w('## Reflection prompts (Debrief 2)');
w();
(C.reflection || []).forEach((t, i) => w((i + 1) + '. ' + t));
w();

// --- Overrides ---------------------------------------------------------------
w('## Every override');
w();
w('Hand-tuned adjustments (SPEC.md 7.6), added after the formula, in the range ' + RULES.overrideMin + ' to +' + RULES.overrideMax + ' per meter. ' + overrides.length + ' options carry one.');
w();
w('| Where | Lever | Counsellor says | Override |');
w('|---|---|---|---|');
for (const o of overrides) w('| ' + o.where + ' | ' + o.lever + ' | ' + esc(o.text) + ' | ' + o.ov + ' |');
w();

// --- RULES ------------------------------------------------------------------
w('## Rules table');
w();
w('From `RULES` in `src/engine.js`. Changes made during calibration, and why, are in the Calibration log at the end of SPEC.md.');
w();
w('**Base effects (skilful wording)**');
w();
w('| Lever | Trust | Confidence | Ownership |');
w('|---|---|---|---|');
for (const l of RULES.levers) w('| ' + LEVER_NAME[l] + ' | ' + RULES.meters.map((m) => signed(RULES.base[l][m])).join(' | ') + ' |');
w();
const S = RULES.state;
w('| Rule | Value |');
w('|---|---|');
for (const q of Object.keys(RULES.wording)) w('| ' + q[0].toUpperCase() + q.slice(1) + ' wording (Round 1) | positive effects × ' + RULES.wording[q].positiveFactor + ', then Trust ' + signed(RULES.wording[q].trustPenalty) + ' |');
w('| Challenge before trust | Trust < ' + S.challengeBeforeTrust.trustBelow + ': row replaced by ' + row(S.challengeBeforeTrust.row) + ' |');
w('| Observe before trust | Trust < ' + S.observeBeforeTrust.trustBelow + ': Trust effect ' + signed(S.observeBeforeTrust.trust) + ' |');
w('| Support at high trust | Trust ≥ ' + S.supportAtHighTrust.trustAtLeast + ': Ownership ' + signed(S.supportAtHighTrust.ownership) + ' |');
w('| Repetition | from the ' + RULES.repetition.streakLength + 'rd consecutive use: positives × ' + RULES.repetition.positiveFactor + '; ' + Object.entries(RULES.repetition.penalties).map(([l, p]) => LEVER_NAME[l] + ' ' + row(p)).join('; ') + ' |');
for (const t of RULES.traitMultipliers) w('| Trait: ' + t.trait + ' `' + t.band + '` | ' + LEVER_NAME[t.lever] + ' ' + t.meter + ' ' + t.sign + ' × ' + t.factor + (t.act ? ' (Act ' + t.act + ' only)' : '') + (t.trustBelow ? ' (while Trust < ' + t.trustBelow + ')' : '') + ' |');
for (const t of RULES.traitCaps) w('| Trait cap: ' + t.trait + ' `' + t.band + '` | ' + t.meter + ' gain at most +' + t.max + ' per decision' + (t.act ? ' in Act ' + t.act : '') + ' |');
const E = RULES.endings;
w('| Early exit | Trust ≤ ' + E.early.trustAtMost + ' at any point |');
w('| Breakthrough | at the end, Ownership ≥ ' + E.breakthrough.ownershipAtLeast + ' and Trust ≥ ' + E.breakthrough.trustAtLeast + '; or Ownership ≥ ' + E.highOwnership.ownershipAtLeast + ' and Trust ≥ ' + E.highOwnership.trustAtLeast + ' |');
w('| Partial | at the end, Trust ≥ ' + E.partial.trustAtLeast + ' and Ownership ≥ ' + E.partial.ownershipAtLeast + '; otherwise Polite exit |');
for (const [e, c] of Object.entries(RULES.carry)) {
  const parts = [];
  if (c.trustCarry !== undefined) parts.push('Trust ' + Math.round(c.trustCarry * 100) + '% of final');
  if (c.trust !== undefined) parts.push('Trust ' + c.trust);
  if (c.confidenceBonus !== undefined) parts.push('Confidence final +' + c.confidenceBonus);
  else if (c.carry) parts.push('Confidence carries');
  if (c.ownership !== undefined) parts.push('Ownership ' + c.ownership);
  if (!c.carry) parts.push('other meters from the profile');
  w('| Round 2 start after ' + e + ' | ' + parts.join(', ') + (RULES.readinessRiseAfter.includes(e) ? '; readiness +1 band' : '') + ' |');
}
w();

// --- Calibration -------------------------------------------------------------
const report = calibrate(C);
w('## Calibration report');
w();
w('From `node tests/calibrate.mjs` (SPEC.md 7.8). Round 1 has 12 options per decision and Round 2 has 4; "random play" picks each option with equal probability. Every path is covered by a memoised walk over distinct states, so the percentages are exact. Round 2 criteria use the median carry-over for each Round 1 ending; reachability is also checked from the lowest and highest.');
w();
w('```text');
w(report.text.replace(/ in [0-9.]+s\./, '.'));
w('```');
w();

// --- Wording tells -------------------------------------------------------------
const tells = wordingTells(C);
w('## Wording tells (Round 1)');
w();
w('From `node tests/wording-tells.mjs` (SPEC.md 9.4, 14.3): length, end punctuation and opening word of each wording, and anything that would let a reader sort the three qualities by surface features.');
w();
w('```text');
w(tells.text);
w('```');
w();

// --- Placeholders --------------------------------------------------------------
const ph = strings(C, []).filter((s) => s.includes('PLACEHOLDER:'));
w('## PLACEHOLDER strings');
w();
w(ph.length ? ph.map((s) => '- ' + s).join('\n') : 'None.');
w();

writeFileSync(join(root, 'docs', 'CONTENT-REVIEW.md'), out.join('\n'));
console.log('wrote docs/CONTENT-REVIEW.md (' + out.length + ' lines; calibration ' + (report.failed ? 'FAILED ' + report.failed : 'passed') + ')');
process.exitCode = report.failed ? 1 : 0;
